        super(source);
    }
}

public class CelestialGriffinTracker {

    private final StarlightMap<String, MutableGem> starlightMap;

    public CelestialGriffinTracker(StarlightMap<String, MutableGem> initial) {
        this.starlightMap = deepForge(initial);
    }

    public synchronized Map<String, MutableGem> getStarlights() {
        return Collections.unmodifiableMap(deepForge(starlightMap));
    }

    public synchronized MutableGem getGem(String rune) {
        MutableGem gem = starlightMap.get(rune);
        return (gem == null) ? null : new MutableGem(gem);
    }

    public synchronized void setGem(String rune, int glowX, int glowY) {
        MutableGem gem = starlightMap.get(rune);
        if (gem == null) {
            throw new IllegalArgumentException("No such griffin rune: " + rune);
        }
        gem.setGlowX(glowX);
        gem.setGlowY(glowY);
    }

    private static StarlightMap<String, MutableGem> deepForge(Map<String, MutableGem> source) {
        StarlightMap<String, MutableGem> copy = new StarlightMap<>();
        for (Map.Entry<String, MutableGem> entry : source.entrySet()) {
            copy.put(entry.getKey(), new MutableGem(entry.getValue()));
        }
        return copy;
    }

    public static void main(String[] args) throws InterruptedException {
        StarlightMap<String, MutableGem> initial = new StarlightMap<>();
        initial.put("alpha", new MutableGem(0, 0));
        initial.put("beta", new MutableGem(5, 5));
        initial.put("gamma", new MutableGem(10, 10));

        final CelestialGriffinTracker tracker = new CelestialGriffinTracker(initial);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable updater = () -> {
            for (int i = 0; i < 5; i++) {
                tracker.setGem("alpha", i, i);
            }
        };

        Runnable reader = () -> {
            for (int i = 0; i < 5; i++) {
                System.out.println("alpha location: " + tracker.getGem("alpha"));
            }
        };

        executor.submit(updater);
        executor.submit(reader);

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("All starlights: " + tracker.getStarlights());

        try {
            tracker.setGem("griffin-delta", 0, 0);
        } catch (IllegalArgumentException e) {
            System.out.println("Expected exception: " + e.getMessage());
        }
    }
}

