import java.math.BigInteger;
import java.util.Arrays;

public class CachingServlet {

    static final class OneValueCache {
        private final BigInteger lastNumber;
        private final BigInteger[] lastFactors;

        OneValueCache(BigInteger i, BigInteger[] factors) {
            lastNumber = i;
            lastFactors = (factors == null) ? null : Arrays.copyOf(factors, factors.length);
        }

        BigInteger[] getFactors(BigInteger i) {
            if (lastNumber == null || !lastNumber.equals(i)) {
                return null;
            }
            return Arrays.copyOf(lastFactors, lastFactors.length);
        }
    }

    private volatile OneValueCache cache = new OneValueCache(null, new BigInteger[0]);

    public BigInteger[] handleRequest(BigInteger value) {
        BigInteger[] factors = cache.getFactors(value);
        if (factors == null) {
            factors = compute(value);
            cache = new OneValueCache(value, factors);
        }
        return factors;
    }

    private BigInteger[] compute(BigInteger i) {
        return new BigInteger[] { i };
    }

    public static void main(String[] args) throws InterruptedException {
        final CachingServlet servlet = new CachingServlet();

        Runnable requestTask = () -> {
            BigInteger[] result = servlet.handleRequest(BigInteger.valueOf(42));
            System.out.println(Thread.currentThread().getName() + " got: " + Arrays.toString(result));
        };

        Thread t1 = new Thread(requestTask);
        Thread t2 = new Thread(requestTask);

        t1.start();
        t2.start();
        t1.join();
        t2.join();
    }
}

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DelegatingVehicleTracker {

    static class Point {
        public final int x;
        public final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    private final ConcurrentHashMap<String, Point> locations;

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        this.locations = new ConcurrentHashMap<String, Point>(initialLocations);
    }

    public Map<String, Point> getLocations() {
        return Collections.unmodifiableMap(locations);
    }

    public Point getLocation(String id) {
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        // Check membership before writing so an unknown id fails fast with a
        // clear IllegalArgumentException instead of risking a NullPointerException.
        if (!locations.containsKey(id)) {
            throw new IllegalArgumentException("No such vehicle: " + id);
        }
        locations.put(id, new Point(x, y));
    }

    public Map<String, Point> getLocationsAsStatic() {
        return Collections.unmodifiableMap(new HashMap<String, Point>(locations));
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, Point> initial = new HashMap<String, Point>();
        initial.put("car1", new Point(0, 0));
        initial.put("car2", new Point(1, 1));

        final DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initial);

        Thread t1 = new Thread(() -> tracker.setLocation("car1", 5, 5));
        Thread t2 = new Thread(() -> {
            try {
                tracker.setLocation("car3", 2, 2);
            } catch (IllegalArgumentException e) {
                System.out.println("Expected failure: " + e.getMessage());
            }
        });

        t1.start();
        t2.start();
        t1.join();
        t2.join();

        System.out.println("car1 location: " + tracker.getLocation("car1"));
        System.out.println("Locations: " + tracker.getLocations());
        System.out.println("Static snapshot: " + tracker.getLocationsAsStatic());
    }
}

