import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ReadWriteMap<K, V> {

    private final Map<K, V> map;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public V put(K key, V value) {
        lock.writeLock().lock();
        try {
            return map.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V remove(K key) {
        lock.writeLock().lock();
        try {
            return map.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        lock.writeLock().lock();
        try {
            map.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clear() {
        lock.writeLock().lock();
        try {
            map.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V get(K key) {
        lock.readLock().lock();
        try {
            return map.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return map.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return map.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(K key) {
        lock.readLock().lock();
        try {
            return map.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(V value) {
        lock.readLock().lock();
        try {
            return map.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public static void main(String[] args) {
        final ReadWriteMap<String, Integer> rwMap = new ReadWriteMap<String, Integer>(new HashMap<String, Integer>());

        rwMap.put("b", 2);
        System.out.println("Reader1: " + rwMap.get("a"));
        System.out.println("Reader2 size: " + rwMap.size());
    }
}

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

public class BoundedHashSet<T> {

    private final Set<T> set;
    private final Semaphore sem;

    public BoundedHashSet(int bound) {
        this.set = Collections.synchronizedSet(new HashSet<T>());
        this.sem = new Semaphore(bound);
    }

    public boolean add(T o) throws InterruptedException {
        sem.acquire();
        boolean wasAdded = false;
        try {
            wasAdded = set.add(o);
            return wasAdded;
        } finally {
            if (!wasAdded) {
                sem.release();
            }
        }
    }

    public boolean remove(Object o) {
        boolean wasRemoved = set.remove(o);
        if (wasRemoved) {
            sem.release();
        }
        return wasRemoved;
    }

    @Override
    public String toString() {
        return set.toString();
    }

    public static void main(String[] args) throws InterruptedException {
        // Kept deliberately small so the reachable state space stays bounded
        // for a model checker while still exercising the add/remove/permit logic.
        final BoundedHashSet<Integer> boundedSet = new BoundedHashSet<>(2);
        ExecutorService executor = Executors.newFixedThreadPool(4);

        executor.execute(() -> {
            try {
                boundedSet.add(1);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        executor.execute(() -> {
            try {
                boundedSet.add(2);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        executor.execute(() -> boundedSet.remove(1));
        executor.execute(() -> {
            try {
                boundedSet.add(3);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final set: " + boundedSet);
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

public class BetterAttributeStore {

    private final Map<String, String> attributes = new HashMap<String, String>();

    public boolean userLocationMatches(String name, String regexp) {
        String key = "users." + name + ".location";
        String location;
        synchronized (this) {
            location = attributes.get(key);
        }
        if (location == null) {
            return false;
        }
        try {
            return Pattern.matches(regexp, location);
        } catch (PatternSyntaxException e) {
            // An invalid regular expression should not escape as an uncaught
            // exception; treat it as "no match" instead.
            return false;
        }
    }

    public synchronized void setAttribute(String key, String value) {
        attributes.put(key, value);
    }

    public static void main(String[] args) {
        final BetterAttributeStore store = new BetterAttributeStore();
        store.setAttribute("users.alice.location", "Boston");

        System.out.println("Alice matches Boston: " + store.userLocationMatches("alice", "Boston"));
        System.out.println("Bob matches anything: " + store.userLocationMatches("bob", ".*"));
    }
}
